{
  "mode": "namespace",
  "namespace": "taskview-orientation",
  "namespaceStatus": "ready",
  "namespaceDescription": "Frozen TaskView orientation experiment tools. Use only the tools declared by this server for repository evidence and TaskView access.",
  "tools": [
    {
      "tool": "assertion",
      "description": "Assert or retract one BASE semantic tuple.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "action": {
            "title": "Action",
            "type": "string"
          },
          "relation": {
            "title": "Relation",
            "type": "string"
          },
          "values": {
            "additionalProperties": true,
            "title": "Values",
            "type": "object"
          },
          "grounding": {
            "anyOf": [
              {
                "items": {
                  "additionalProperties": true,
                  "type": "object"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Grounding"
          }
        },
        "required": [
          "action",
          "relation",
          "values"
        ],
        "title": "assertionArguments"
      }
    },
    {
      "tool": "describe",
      "description": "Describe frozen relations, derivations, currentness, and optionally one tuple's grounding.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "why": {
            "anyOf": [
              {
                "additionalProperties": true,
                "type": "object"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Why"
          }
        },
        "title": "describeArguments"
      }
    },
    {
      "tool": "query_sql",
      "description": "Run read-only SQL over declared semantic relation tables.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "sql": {
            "title": "Sql",
            "type": "string"
          },
          "parameters": {
            "anyOf": [
              {
                "items": {},
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Parameters"
          }
        },
        "required": [
          "sql"
        ],
        "title": "query_sqlArguments"
      }
    },
    {
      "tool": "read_source",
      "description": "Read an inclusive line range from one participant-visible source file.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "title": "Path",
            "type": "string"
          },
          "start_line": {
            "default": 1,
            "title": "Start Line",
            "type": "integer"
          },
          "end_line": {
            "default": 10000,
            "title": "End Line",
            "type": "integer"
          }
        },
        "required": [
          "path"
        ],
        "title": "read_sourceArguments"
      }
    },
    {
      "tool": "rerun",
      "description": "Rerun a registered derivation under its fixture-owned contract.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "relation": {
            "title": "Relation",
            "type": "string"
          }
        },
        "required": [
          "relation"
        ],
        "title": "rerunArguments"
      }
    },
    {
      "tool": "search_source",
      "description": "Search participant-visible source text under a relative scope.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "title": "Query",
            "type": "string"
          },
          "scope": {
            "default": ".",
            "title": "Scope",
            "type": "string"
          }
        },
        "required": [
          "query"
        ],
        "title": "search_sourceArguments"
      }
    },
    {
      "tool": "write_scratch",
      "description": "Write a UTF-8 scratch artifact outside the read-only source tree.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "title": "Path",
            "type": "string"
          },
          "content": {
            "title": "Content",
            "type": "string"
          }
        },
        "required": [
          "path",
          "content"
        ],
        "title": "write_scratchArguments"
      }
    }
  ]
}
